for(const dialog of document.querySelectorAll("dialog")){dialog.addEventListener("close",()=>{hideSourceContext();syncToasts();});dialog.addEventListener("toggle",()=>{if(dialog.open)syncToasts();});}$("sourceDialog").addEventListener("close",()=>{$("sourceUrl").value="";$("sourceUrl").dataset.sourceUrl="";S.streams=[];S.sourceRoom=null;});
function bytesToBase64(bytes){let text="";for(let i=0;i<bytes.length;i+=0x8000)text+=String.fromCharCode(...bytes.subarray(i,i+0x8000));return btoa(text);}
$("importBtn").onclick=()=>$("importFile").click();$("importFile").onchange=async()=>{const file=$("importFile").files?.[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error("文件过大，请使用 5 MB 以内的直播间列表。");const format=file.name.toLowerCase().endsWith(".kd")?"kd":file.name.toLowerCase().endsWith(".csv")?"csv":"";if(!format)throw new Error("请选择 .kd 或 .csv 文件。");$("importBtn").disabled=true;const content_base64=bytesToBase64(new Uint8Array(await file.arrayBuffer()));const result=await api("/api/import","POST",{format,content_base64});showBatchResult(result,"文件导入结果");await refresh();}catch(e){toast(e.message,"error");}finally{$("importFile").value="";$("importBtn").disabled=false;}};
$("exportBtn").onclick=()=>{setText($("exportScope"),S.selected.size?`将导出已选的 ${S.selected.size} 个直播间。`:`将导出全部 ${S.rooms.length} 个直播间。`);$("exportDialog").showModal();};$("exportSaveBtn").onclick=async()=>{const button=$("exportSaveBtn");button.disabled=true;try{const body={format:$("exportFormat").value};if(S.selected.size)body.ids=[...S.selected];const result=await api("/api/export","POST",body);if(typeof result.content_base64!=="string")throw new Error("导出内容无效，请重试。");const binary=atob(result.content_base64),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0)),blob=new Blob([bytes],{type:result.mime||"application/octet-stream"}),url=URL.createObjectURL(blob),link=el("a");link.href=url;link.download=result.filename||("直播间列表."+body.format);document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);$("exportDialog").close();toast("已生成仅含直播间 ID 和主页链接的列表，请选择保存位置。","info");}catch(e){toast(e.message,"error");}finally{button.disabled=false;}};
if(window.chrome&&window.chrome.webview)window.chrome.webview.addEventListener("message",event=>{if(event.data?.event==="recording-directory-selected"){const input=$(event.data.request_id);if(input&&["recordingDirectory","recordDirectory","roomRecordDirectory"].includes(input.id)&&!event.data.cancelled&&typeof event.data.path==="string")input.value=event.data.path;return;}if(event.data&&event.data.event==="authorized"){S.auth={...S.auth,douyin_authorized:true,login_in_progress:false};S.authPrompted=true;updateAuth();toast("抖音已连接，可以开始使用了");refresh();}});
document.addEventListener("visibilitychange",()=>{if(!document.hidden)refresh();});refresh();setInterval(refresh,1000);



function updateAccessModeHint(){setText($("accessModeHint"),$("monitorIdentityIsolation").checked?"房间状态使用独立匿名身份，不携带抖音登录 Cookie；授权只用于必要的账号解析。优先使用固定直播间链接。":($("douyinAccessMode").value==="authorized"?"使用已保存的官方登录资料检查直播间，可能与手机观看产生账号设备冲突。":"匿名监控不携带账号观看身份，有助于与手机观看同时使用。"));}
$("douyinAccessMode").onchange=updateAccessModeHint;$("monitorIdentityIsolation").onchange=updateAccessModeHint;
function updateDiskStatus(){const disk=S.maintenance.disk||{},free=disk.free_bytes,min=disk.min_free_bytes,known=typeof free==="number"&&Number.isFinite(free),low=disk.recording_allowed===false;const detail=known?`录制磁盘剩余 ${(free/1024**3).toFixed(1)} GiB`:(disk.error||"磁盘空间等待更新");setText($("diskSpaceStatus"),detail+(known&&typeof min==="number"?`，保护阈值 ${(min/1024**3).toFixed(1)} GiB`:""));$("diskSpaceNotice").classList.toggle("hidden",!low);setText($("diskSpaceNotice"),low?(known?`${detail}，低于保护阈值，已暂停录制。释放空间后会自动恢复。`:(disk.error||"无法读取磁盘空间，已暂停录制。")):"");}
